from __future__ import annotations

from pydantic import Field
from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, Optional, SdkBaseModel
from .evaluate_code_error_detail import EvaluateCodeErrorDetail, EvaluateCodeErrorDetailDict


class EvaluateCodeResponse(SdkBaseModel):
    evaluation_result: Optional[str] = Field(default=UNSET, alias="evaluationResult")
    """The result of the evaluation operation."""

    error: Optional[EvaluateCodeErrorDetail] = UNSET
    logs: Optional[list[str]] = UNSET
    """A list of logs that were generated by calls to util.log.info and util.log.error in the evaluated code."""

    stash: Optional[str] = UNSET
    """An object available inside each resolver and function handler. A single stash object lives through a single
    resolver run. Therefore, you can use the stash to pass arbitrary data across request and response handlers and
    across functions in a pipeline resolver."""

    out_errors: Optional[str] = Field(default=UNSET, alias="outErrors")
    """The list of runtime errors that are added to the GraphQL operation response."""


class EvaluateCodeResponseDict(TypedDict):
    evaluation_result: NotRequired[str]
    error: NotRequired[EvaluateCodeErrorDetailDict]
    logs: NotRequired[list[str]]
    stash: NotRequired[str]
    out_errors: NotRequired[str]
